static rpmRC ensureDir(char *binRpm) /* <=== ensureDir */ 
{
    rpmRC rc = RPMRC_OK;
    char *binDir = strchr(binRpm, '/');
    char *dn = NULL;
    if (binDir) {
	struct stat st;
	*binDir = '\0';
	dn = rpmGetPath("%{_rpmdir}/", binRpm, NULL);
	if (stat(dn, &st) < 0) {
	    switch (errno) {
	    case ENOENT:
		if (mkdir(dn, 0755) == 0 || errno == EEXIST)
		    break;
	    default:
		rpmlog(RPMLOG_ERR,_("cannot create %s: %s\n"),
			dn, strerror(errno));
		rc = RPMRC_FAIL;
		break;
	    }
	}
    }
    free(dn);
    return rc;
}

